entries.commands:
# ===== 创建 VLAN 并划入端口（H3C Comware7）=====
system-view
vlan {{vlan_id}}
 name {{vlan_name}}
 quit
interface range GigabitEthernet {{port_start}} to GigabitEthernet {{port_end}}
 port link-type access
 port access vlan {{vlan_id}}
 undo shutdown
 quit
save force

# ===== 配置 Trunk 口（H3C Comware7）=====
system-view
interface GigabitEthernet {{port}}
 port link-type trunk
 port trunk permit vlan {{vlan_list}}
 port trunk pvid vlan {{pvid}}
 undo shutdown
 quit
save force
display interface GigabitEthernet {{port}} brief

# ===== 静态路由（H3C Comware7）=====
system-view
ip route-static {{dest_net}} {{masklen}} {{next_hop}}
ip route-static 0.0.0.0 0 {{next_hop}}
ip route-static {{dest_net}} {{masklen}} {{backup_hop}} preference {{preference}}
display ip routing-table {{dest_net}}
save force

# ===== OSPF 基本配置（H3C Comware7）=====
system-view
ospf {{process_id}} router-id {{router_id}}
 area {{area_id}}
  network {{network}} {{wildcard}}
  quit
 silent-interface GigabitEthernet{{silent_port}}
 quit
display ospf peer
display ospf routing
save force

# ===== ACL 配置与下发（H3C Comware7）=====
system-view
acl advanced {{acl_number}}
 rule 5 permit ip source {{src_net}} {{src_wild}} destination {{dst_net}} {{dst_wild}}
 rule 10 deny ip
 quit
interface GigabitEthernet {{port}}
 packet-filter {{acl_number}} inbound
 quit
display acl {{acl_number}}
save force

# ===== NAT / Easy IP（H3C Comware7）=====
system-view
acl basic {{acl_number}}
 rule 5 permit source {{src_net}} {{src_wild}}
 quit
interface GigabitEthernet {{outside_port}}
 ip address {{outside_ip}} {{outside_mask}}
 nat outbound {{acl_number}}
 quit
! 使用公网地址池做 PAT：
! nat address-group {{group_id}}
!  address {{pool_start}} {{pool_end}}
!  quit
! interface GigabitEthernet {{outside_port}}
!  nat outbound {{acl_number}} address-group {{group_id}}
display nat outbound
display nat session verbose
save force

# ===== SNMP 配置（H3C Comware7）=====
system-view
snmp-agent
snmp-agent sys-info version v2c
snmp-agent community read {{ro_community}}
snmp-agent community write {{rw_community}}
snmp-agent sys-info location {{location}}
snmp-agent sys-info contact {{contact}}
snmp-agent target-host trap address udp-domain {{nms_ip}} params securityname {{ro_community}} v2c
snmp-agent trap enable
display snmp-agent community
save force
